export interface JuewuTurnRecord {
	phaseNumber: number;
	targets: string[];
}

export function getLaMaupinAttackRange(currentRange: number, hasEquippedCixiong: boolean): number {
	return hasEquippedCixiong ? 5 : Math.max(2, currentRange);
}

export function shouldGainKuFromSword(isJuewuSha: boolean, isKuangmingAwakened: boolean, hasGainedKuThisTurn: boolean): boolean {
	return !isJuewuSha && (!isKuangmingAwakened || !hasGainedKuThisTurn);
}

export function getCurrentJuewuTargets(record: JuewuTurnRecord | undefined, phaseNumber: number): string[] {
	return record?.phaseNumber === phaseNumber ? record.targets : [];
}

export function shouldIgnoreShaCount(targets: string[], usedTargets: string[]): boolean {
	return targets.length > 0 && targets.every(target => !usedTargets.includes(target));
}

export function recordJuewuTargets(phaseNumber: number, usedTargets: string[], targets: string[]): JuewuTurnRecord {
	return {
		phaseNumber,
		targets: [...new Set([...usedTargets, ...targets])],
	};
}
